code-changes.before:
// Basic mode toggle button
<button onClick={() => useStore.setState({ mode: mode === '2d' ? '3d' : '2d' })}>
  {mode === '2d' ? '3D View' : '2D View'}
</button>

code-changes.after:
// Enhanced mode toggle with smooth transitions
<motion.button
  whileHover={{ scale: 1.05 }}
  whileTap={{ scale: 0.95 }}
  onClick={handleModeToggle}
  className="mode-toggle-elevated"
  aria-describedby="mode-toggle-help"
>
  <motion.div
    animate={{ rotateY: mode === '3d' ? 180 : 0 }}
    transition={{ duration: 0.6, ease: "easeInOut" }}
  >
    {mode === '2d' ? '🎨 Enter 3D' : '📊 Back to 2D'}
  </motion.div>
</motion.button>
